import {signatureArtReady} from './signature-effects.js?v=0.87.0';
import {combatArtReady,combatArtSrc} from './combat-art.js?v=0.90.20';
import {DATA} from './data.js?v=0.87.0';import {effectSpec,effectHTML,PALETTES} from './effects.js?v=0.87.0';import {learnTreeHTML} from './learn-tree.js?v=0.90.18';
const $=id=>document.getElementById(id);let timer;
for(const type of Object.keys(PALETTES))$('type').add(new Option(type,type));
function filter(){const needle=$('search').value.toLowerCase(),type=$('type').value,old=$('move').value,moves=DATA.moves.filter(m=>(!type||m.type_id===type)&&(m.name+' '+m.type_id+' '+m.effect_text).toLowerCase().includes(needle));$('move').replaceChildren(...moves.map(m=>new Option(m.name+' · '+m.type_id,m.id)));if(moves.some(m=>String(m.id)===old))$('move').value=old;$('play').disabled=!moves.length;preview();}
let previewRequest=0;async function preview(){const request=++previewRequest;clearTimeout(timer);const move=DATA.moves.find(m=>String(m.id)===$('move').value);if(!move){$('info').textContent='No matching moves.';$('preview-fx').replaceChildren();return;}await signatureArtReady(move);if(request!==previewRequest)return;const spec=effectSpec(move,{}),stage=document.querySelector('.preview-stage'),self=['SELF','ACTIVE_SIDE'].includes(move.target),x=stage.clientWidth*(self?0.2:0.8),y=stage.clientHeight-140,dx=self?0:-stage.clientWidth*.6;$('preview-fx').innerHTML=`<div class="fx-anchor" style="left:${x}px;top:${y}px;--source-x:${dx}px;--source-y:0px">${effectHTML(move,{damage:move.power?24:0,targetArt:document.querySelector(self?'.caster':'.target').src})}</div>`;$('info').replaceChildren();const h=document.createElement('h2');h.textContent=move.name;const meta=document.createElement('p');meta.textContent=`${move.type_id} · ${move.category} · ${move.power?'Power '+move.power:'Status'} · ${move.pp} PP · Priority ${move.priority||0} · ${spec.key||spec.style}`;const effect=document.createElement('p');effect.textContent=move.effect_text;if(spec.sequence){const sequence=document.createElement('p');sequence.textContent=spec.sequence;$('info').append(sequence);}$('info').append(h,meta,effect);if(move.runtime_binding){const binding=document.createElement('small');binding.textContent=move.runtime_binding;$('info').append(binding);}timer=setTimeout(()=>$('preview-fx').replaceChildren(),Math.max(1700,spec.duration+200));}
function tree(){const species=DATA.species.find(s=>s.id===$('species').value);$('tree').innerHTML=learnTreeHTML({species,level:1,moves:[],evolutionHistory:[]});}
for(const s of DATA.species)$('species').add(new Option(String(s.dex_number).padStart(3,'0')+' · '+s.name+' · '+s.growth_archetype,s.id));$('species').onchange=tree;$('search').oninput=filter;$('type').onchange=filter;$('move').onchange=preview;$('play').onclick=preview;filter();const initial=new URLSearchParams(location.search).get('move')||'38';if(DATA.moves.some(m=>String(m.id)===initial)){$('move').value=initial;preview();}tree();

for(const [cls,id] of [['caster','001'],['target','007']])combatArtReady(id).then(ready=>{if(ready)document.querySelector('.'+cls).src=combatArtSrc(id);});
